	douglasPeucker(points, startIndex, endIndex, epsilon) {
		// Find the point with the maximum distance
var maxDistance = 0;
var maxIndex = 0;

var start = points[startIndex];
var end = points[endIndex];

		// Handle case where start and end are very close
var lineLength = sqrt(
			pow(end.x - start.x, 2) +
			pow(end.y - start.y, 2)
		);

		if (lineLength < epsilon) {
			return [points[startIndex]];
		}

		for (let i = startIndex + 1; i < endIndex; i++) {
			var distance = this.perpendicularDistance(points[i], start, end);

			if (distance > maxDistance) {
				maxDistance = distance;
				maxIndex = i;
			}
		}

		// If max distance is greater than epsilon, recursively simplify
		if (maxDistance > epsilon) {
var leftResults = this.douglasPeucker(points, startIndex, maxIndex, epsilon);
var rightResults = this.douglasPeucker(points, maxIndex, endIndex, epsilon);

			// Combine the results, removing duplicate maxIndex
			return leftResults.concat(rightResults.slice(1));
		} else {
			// No point was far enough - use only endpoints
			return [points[startIndex], points[endIndex]];
		}
	}

	perpendicularDistance(point, lineStart, lineEnd) {
var dx = lineEnd.x - lineStart.x;
var dy = lineEnd.y - lineStart.y;

		// Handle vertical and horizontal lines specially
		if (dx === 0) {
			return abs(point.x - lineStart.x);
		}
		if (dy === 0) {
			return abs(point.y - lineStart.y);
		}

var slope = dy / dx;
var intercept = lineStart.y - slope * lineStart.x;

		// Distance from point to line: |Ax + By + C| / sqrt(A² + B²)
		// For a line in form y = mx + b, this becomes |mx - y + b| / sqrt(m² + 1)
		return abs(slope * point.x - point.y + intercept) / sqrt(slope * slope + 1);
	}

