function randomLetterTest() {
var foundLetter = false;
	var iter = 0;
var letter = null;
var _wG_3 = 0; while ((!foundLetter && iter < 20) && ++_wG_3 < 20000) {
		iter++;
var rlidx = floor(random(allowedLetters.length));
var rlet = allowedLetters.charAt(rlidx);
		if (!kboard.fadeLetters.includes(rlet)) {
			if (currentLetters[activeIndex] != rlet) {
				if (!testLetter(rlet)) {
					foundLetter = true;
					letter = rlet;
				}

			}
		}
	}
	if (foundLetter) {
		kboard.fadeKeyWrong(letter);
	}
}

function testLetter(whichLetter) {
var wordTest = "";
	for (let i = 0; i < activeIndex; i++) {
		wordTest += currentLetters[i];
	}
	wordTest += whichLetter;
	for (let i = activeIndex + 1; i < lettersWord; i++) {
		wordTest += currentLetters[i];
	}
	if (validWords.includes(wordTest)) {
		return true;
	}
	return false;
}

function getCurrentWord() {
	var completeWord = "";
	for (let i = 0; i < lettersWord; i++) {
		completeWord += currentLetters[i];
	}
	if (lettersWord == 5) {
		completeWord = completeWord.toLowerCase();
	}
	return completeWord;
}

function checkCurrentWord(completeWord) {

	//console.log(completeWord);
	if (validWords.includes(completeWord)) {
		return true;
	} else {
		return false;
	}
}

function checkPossibility() {
	//see if any letter can solve current challenge
	var wordTest = "";
	for (let i = 0; i < activeIndex; i++) {
		wordTest += currentLetters[i];
	}
var lastLetters = "";
	for (let i = activeIndex + 1; i < lettersWord; i++) {
		lastLetters += currentLetters[i];
	}
var currentActiveLetter = currentLetters[activeIndex];
	for (let l = 0; l < allowedLetters.length; l++) {
var testlet = allowedLetters.charAt(l);
		if (testlet != currentActiveLetter) {
var testString = wordTest;
			testString += testlet;
			testString += lastLetters;
			if (validWords.includes(testString)) {
				//console.log(testString);
				lastSolution = testString;
				return true;
			}
		}
	}
	return false;
}




class LetterHolder {
	constructor(inLetter) {
		this.letter = inLetter;
		this.bgcol = 'lightblue';
		this.activeInput = false;
		this.flasher = 0;
		this.redFlash = 0;
		this.letterMorpher = null;
		this.targetLetter = null;
		this.morphStep = 0;
	}

	setLetterMorphTo(inTargetLetter) {
		this.targetLetter = inTargetLetter;
		this.letterMorpher = new LetterTween(this.letter, this.targetLetter, morphSteps);
		this.morphStep = 0;
	}

	renderAt(offsetx, offsety) {
		fill(this.bgcol);
		rect(offsetx, offsety, lblockw, lblockh, 10);


		if (this.activeInput) {
var flashcol;
			if (this.redFlash > 0) {
				this.redFlash--;
				flashcol = color(255, 0, 0, 100);
				fill(flashcol);
				rect(offsetx, offsety, lblockw, lblockh, 10);
			} else {
				this.flasher += 0.05;
var fval = abs(sin(this.flasher));
var brt = fval * 255;
				flashcol = color(255, 255, 255, brt);
				fill(flashcol);
var ttm = turnTimer / timeLimit;
var flasshh = ttm * lblockh;
				rect(offsetx, offsety + flasshh, lblockw, lblockh - flasshh, 10);
			}


		}
		if (useLetterMorph && this.letterMorpher != null) {

			push();
			translate(offsetx + (lblockw * 0.5), offsety + lblockh - 60);
var tv = this.morphStep / morphSteps;
			this.letterMorpher.fullRender(color(0, 0, 0), this.bgcol, tv);
			pop();
			this.morphStep++;
			if (this.morphStep == morphSteps) {
				//done morphing
				this.letter = this.targetLetter;
				this.letterMorpher = null;
			}

		} else {
			fill('black');
			textSize(180);
			textAlign(CENTER)
			textStyle(BOLD);
			text(this.letter, offsetx + (lblockw * 0.5), offsety + lblockh - 60);
		}

	}
}
